import React, { useState } from 'react';
import { useOSStore } from '../store/useOSStore';

export default function BulletinApp() {
  const [isGlitched, setIsGlitched] = useState(false);
  const [statusMessage, setStatusMessage] = useState('');
  const addCredits = useOSStore((s) => s.addCredits);
  const addXP = useOSStore((s) => s.addXP);

  const triggerGlitch = () => {
    setIsGlitched(true);
    setStatusMessage('⚠️ PRISM CORRUPTION SPIKE DETECTED! SCANNING VEIL...');
    setTimeout(() => setIsGlitched(false), 1800);
  };

  const handleCheckIn = () => {
    addCredits(100);
    addXP(50);
    setStatusMessage('✅ Checked in at Cyacademy Bulletin Node! +100 Credits, +50 XP');
    setTimeout(() => setStatusMessage(''), 4000);
  };

  const handleSyncSquad = () => {
    setStatusMessage('⚡ Squad Synced: 4 Operatives Active on Mesh Network.');
    setTimeout(() => setStatusMessage(''), 4000);
  };

  return (
    <div
      className={`relative flex h-full w-full flex-col bg-slate-950 p-4 text-white text-xs select-none overflow-auto transition-all ${
        isGlitched ? 'filter invert contrast-200 hue-rotate-180 animate-pulse' : ''
      }`}
    >
      {/* Background Shimmer & Glyph Overlay */}
      <div className="absolute inset-0 bg-gradient-to-r from-cyan-500/5 via-violet-500/5 to-pink-500/5 pointer-events-none" />

      {/* ------------------------------------------------------------------ */}
      {/* HEADER NODE BAR                                                    */}
      {/* ------------------------------------------------------------------ */}
      <div className="relative z-10 flex items-center justify-between rounded-xl border border-[#4DF3FF]/40 bg-black/40 p-3 shadow-lg backdrop-blur-md">
        <div className="flex items-center gap-2 font-bold text-cyan-300 tracking-wider">
          <span className="text-violet-400">✦</span>
          <span>CYACADEMY BULLETIN NODE</span>
        </div>

        {/* Status Pill */}
        <div className="flex items-center gap-3 text-[10px] font-mono text-white/70">
          <span>Time: <strong className="text-amber-300">Evening</strong></span>
          <span className="text-white/30">•</span>
          <span>Veil Status: <strong className={isGlitched ? 'text-pink-400 animate-bounce' : 'text-cyan-400'}>Flicker</strong></span>
          <span className="text-white/30">•</span>
          <span>House: <strong className="text-violet-300">Vector</strong></span>
          <span className="text-white/30">•</span>
          <span>Role: <strong className="text-pink-400">Anti</strong></span>
        </div>
      </div>

      {statusMessage && (
        <div className="relative z-10 mt-2 rounded-lg border border-amber-400/40 bg-amber-500/10 p-2 text-center text-[11px] font-bold text-amber-300">
          {statusMessage}
        </div>
      )}

      {/* ------------------------------------------------------------------ */}
      {/* 3-COLUMN GLASS PANEL GRID                                          */}
      {/* ------------------------------------------------------------------ */}
      <div className="relative z-10 my-4 grid grid-cols-1 gap-4 md:grid-cols-3 flex-1 min-h-0">
        {/* COLUMN 1: CAMPUS FEED */}
        <div className="flex flex-col space-y-3 rounded-xl border border-[#4DF3FF]/30 bg-white/10 p-3 backdrop-blur-md shadow-lg">
          <div className="flex items-center justify-between border-b border-cyan-400/20 pb-1.5 font-bold text-cyan-300">
            <span>CAMPUS FEED</span>
            <span className="text-[10px] text-white/40">Live Grid</span>
          </div>

          {/* Card 1: Class Updates */}
          <div className="rounded-lg border border-cyan-500/20 bg-black/40 p-2.5 space-y-1">
            <div className="font-bold text-cyan-300 flex items-center gap-1.5">
              <span>▣</span> Class Updates
            </div>
            <div className="text-white/80 text-[11px]">Syntax HW: Quantum Recursion</div>
            <div className="text-white/50 text-[10px]">Aethercore Lab 4 Open until 22:00</div>
          </div>

          {/* Card 2: Clubs & Social */}
          <div className="rounded-lg border border-violet-500/20 bg-black/40 p-2.5 space-y-1">
            <div className="font-bold text-violet-300 flex items-center gap-1.5">
              <span>▣</span> Clubs & Social
            </div>
            <div className="text-white/80 text-[11px]">Netrunner Art Club @ 19:00</div>
            <div className="text-white/50 text-[10px]">Robotics Build: Graviton Rig</div>
          </div>

          {/* Card 3: Pulse Trending */}
          <div className="rounded-lg border border-pink-500/20 bg-black/40 p-2.5 space-y-1">
            <div className="font-bold text-pink-300 flex items-center gap-1.5">
              <span>▣</span> Pulse Trending
            </div>
            <div className="text-amber-300 font-mono text-[11px]">#DormDrama</div>
            <div className="text-cyan-300 font-mono text-[11px]">#OddSighting</div>
          </div>
        </div>

        {/* COLUMN 2: MISSIONS & OPS */}
        <div className="flex flex-col space-y-3 rounded-xl border border-[#C77CFF]/30 bg-white/10 p-3 backdrop-blur-md shadow-lg">
          <div className="flex items-center justify-between border-b border-violet-400/20 pb-1.5 font-bold text-violet-300">
            <span>MISSIONS & OPS</span>
            <span className="text-[10px] text-pink-400">PRISM Spike</span>
          </div>

          {/* Card 1: DGA Alerts */}
          <div className="rounded-lg border border-red-500/30 bg-red-950/20 p-2.5 space-y-1">
            <div className="font-bold text-red-400 flex items-center gap-1.5">
              <span>▣</span> DGA Alerts
            </div>
            <div className="text-red-300 text-[11px] font-semibold">⚠️ Perimeter Breach Alert</div>
            <div className="text-white/60 text-[10px]">Patrol Route: Sector 7 Subnet</div>
          </div>

          {/* Card 2: Career Tasks */}
          <div className="rounded-lg border border-violet-500/20 bg-black/40 p-2.5 space-y-1">
            <div className="font-bold text-violet-300 flex items-center gap-1.5">
              <span>▣</span> Career Tasks
            </div>
            <div className="text-white/80 text-[11px]">Faith Medical Intake Clearance</div>
            <div className="text-white/50 text-[10px]">Archive Scan: Mireth Records</div>
          </div>

          {/* Card 3: PRISM Activity */}
          <div className="rounded-lg border border-pink-500/40 bg-pink-950/20 p-2.5 space-y-1">
            <div className="font-bold text-pink-400 flex items-center justify-between">
              <span className="flex items-center gap-1.5"><span>▣</span> PRISM Activity</span>
              <span className="text-[9px] uppercase px-1 rounded bg-pink-500/20">Corrupted</span>
            </div>
            <div className="text-pink-300 font-mono text-[11px]">Corruption Level ↑ 14.8%</div>
            <div className="text-white/50 text-[10px]">App Lockdown: Sector 9 Mesh</div>
          </div>
        </div>

        {/* COLUMN 3: SIGNALS & LORE */}
        <div className="flex flex-col space-y-3 rounded-xl border border-[#FFD86B]/30 bg-white/10 p-3 backdrop-blur-md shadow-lg">
          <div className="flex items-center justify-between border-b border-amber-400/20 pb-1.5 font-bold text-amber-300">
            <span>SIGNALS & LORE</span>
            <span className="text-[10px] text-amber-300">Veil Motes</span>
          </div>

          {/* Card 1: City Anomalies */}
          <div className="rounded-lg border border-amber-500/20 bg-black/40 p-2.5 space-y-1">
            <div className="font-bold text-amber-300 flex items-center gap-1.5">
              <span>▣</span> City Anomalies
            </div>
            <div className="text-white/80 text-[11px]">Glassline Flicker in Sprawl</div>
            <div className="text-white/50 text-[10px]">Sub-Aureline Frequency Hum</div>
          </div>

          {/* Card 2: Aethercore Echoes (with Redacted Text) */}
          <div className="rounded-lg border border-cyan-500/20 bg-black/40 p-2.5 space-y-1">
            <div className="font-bold text-cyan-300 flex items-center gap-1.5">
              <span>▣</span> Aethercore Echoes
            </div>
            <div className="text-cyan-200 font-mono text-[11px]">Fragment #07: "Protocol Unread"</div>
            <div className="rounded bg-black/60 p-1 font-mono text-pink-400 text-[10px] tracking-widest">
              [ ████████████████ ]
            </div>
          </div>

          {/* Card 3: Lineage Keys */}
          <div className="rounded-lg border border-amber-500/30 bg-black/40 p-2.5 space-y-1">
            <div className="font-bold text-amber-400 flex items-center gap-1.5">
              <span>▣</span> Lineage Keys
            </div>
            <div className="text-amber-200 text-[11px]">Celestial Glyph Activated</div>
            <div className="text-white/50 text-[10px]">Mark: "Seraphima Lineage"</div>
          </div>
        </div>
      </div>

      {/* ------------------------------------------------------------------ */}
      {/* ACTION BUTTON FOOTER BAR                                           */}
      {/* ------------------------------------------------------------------ */}
      <div className="relative z-10 flex flex-wrap items-center justify-between gap-2 rounded-xl border border-white/20 bg-black/50 p-2.5 backdrop-blur-md">
        <div className="flex flex-wrap items-center gap-2">
          <button
            onClick={handleCheckIn}
            className="rounded-lg border border-emerald-500/40 bg-emerald-500/20 px-3 py-1.5 font-bold text-emerald-300 hover:bg-emerald-500/40 transition"
          >
            [ CHECK IN ]
          </button>
          <button
            onClick={handleSyncSquad}
            className="rounded-lg border border-cyan-500/40 bg-cyan-500/20 px-3 py-1.5 font-bold text-cyan-300 hover:bg-cyan-500/40 transition"
          >
            [ SYNC SQUAD ]
          </button>
          <button
            onClick={triggerGlitch}
            className="rounded-lg border border-pink-500/50 bg-pink-500/20 px-3 py-1.5 font-bold text-pink-300 hover:bg-pink-500/50 hover:text-white transition animate-pulse"
          >
            [ SCAN VEIL ]
          </button>
          <button
            onClick={() => {
              setStatusMessage('📡 Pulse update shared to Cyacademy Mesh Network.');
              setTimeout(() => setStatusMessage(''), 3000);
            }}
            className="rounded-lg border border-violet-500/40 bg-violet-500/20 px-3 py-1.5 font-bold text-violet-300 hover:bg-violet-500/40 transition"
          >
            [ PULSE SHARE ]
          </button>
        </div>

        <button
          onClick={() => {
            setStatusMessage('📜 Cyacademy Logs archived to miraverseDb.');
            setTimeout(() => setStatusMessage(''), 3000);
          }}
          className="rounded-lg border border-amber-500/40 bg-amber-500/20 px-3 py-1.5 font-bold text-amber-300 hover:bg-amber-500/40 transition"
        >
          [ ARCHIVE LOGS ]
        </button>
      </div>
    </div>
  );
}
